{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "In patients with alcoholic cirrhosis, tolfenamic acid (a carboxylic acid/arylamine drug) had ~100% absolute oral bioavailability, demonstrating that this chemical class can achieve high F under the query condition.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Bumetanide, a sulfamoylbenzoic acid loop diuretic closely related to the query, had absolute oral bioavailability of 0.588 ± 0.096 in healthy subjects, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Hydrochlorothiazide, a sulfonamide diuretic with a chlorophenyl-sulfamoyl motif, has oral bioavailability of ~65–70% in humans, supporting high F for the sulfonamide-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Azosemide, a furosemide analogue, has low oral bioavailability (10–19%) in humans, suggesting that some close analogues can fall below the 20% threshold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C06"],
      "claim": "The furosemide acyl glucuronide metabolite had a reported F of 0.15 after oral furosemide; however, this reflects metabolite disposition rather than parent furosemide bioavailability, so it is weak contrary evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "High: the query is furosemide; related loop diuretics (bumetanide) and sulfonamide diuretics (HCTZ) show F well above 20%, and a carboxylic acid NSAID in cirrhosis showed ~100% F. The low values for azosemide and the acyl glucuronide metabolite are less transferable (structural analog with tetrazole/thiophene; metabolite endpoint) and do not outweigh the high-F evidence.",
  "evidence_gaps": [
    "No direct parent furosemide absolute oral bioavailability record is present in the evidence set.",
    "Azosemide low-F data are from healthy or unspecified patients, not specifically cirrhosis.",
    "The furosemide acyl glucuronide record measures metabolite disposition, not parent furosemide bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

